package com.c203.limit.domain.inquiry.entity;
import java.time.OffsetDateTime;import com.c203.limit.domain.member.entity.Member;import com.c203.limit.global.exception.*;import jakarta.persistence.*;
@Entity @Table(name="inquiry") public class Inquiry{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="inquiry_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private Member member;@Column(name="inquiry_type",nullable=false)private String category;@Column(nullable=false)private String title;@Column(nullable=false,columnDefinition="text")private String content;@Column(nullable=false)private String status;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt;@Column(name="closed_at")private OffsetDateTime closedAt;protected Inquiry(){}public void changeStatus(String next){boolean valid=("OPEN".equals(status)&&"IN_PROGRESS".equals(next))||("IN_PROGRESS".equals(status)&&"ANSWERED".equals(next))||("ANSWERED".equals(status)&&"CLOSED".equals(next));if(!valid)throw new BusinessException(ErrorCode.INVALID_INPUT_VALUE);status=next;if("CLOSED".equals(next))closedAt=OffsetDateTime.now();}public void answered(){if("CLOSED".equals(status))throw new BusinessException(ErrorCode.INVALID_INPUT_VALUE);status="ANSWERED";}public Long getId(){return id;}public Member getMember(){return member;}public String getCategory(){return category;}public String getTitle(){return title;}public String getContent(){return content;}public String getStatus(){return status;}public OffsetDateTime getCreatedAt(){return createdAt;}public OffsetDateTime getClosedAt(){return closedAt;}}
